﻿import React from 'react';
import {AbsoluteFill} from 'remotion';
import {useS, en, T, DUR, words, clamp, interpolate, Easing, h, Camara, tono} from './kit';

// FE 2026-11-21 08:00 — oración por la hija que no sale de su cuarto (Lucas 15:20). Sin SFX (BIBLIA FE: solo voz y música), sin texto dibujado.
export const SUBS = {arriba: 230, acento: '#ffd9a0'};

type V = [number, number];
const E = Easing.inOut(Easing.cubic);
const kf = (s: number, p: [number, number][]) => interpolate(s, p.map((q) => q[0]), p.map((q) => q[1]), {...clamp, easing: E});
const kv = (s: number, p: [number, V][]): V => [kf(s, p.map((q) => [q[0], q[1][0]] as [number, number])), kf(s, p.map((q) => [q[0], q[1][1]] as [number, number]))];
const win = (s: number, a: number, b: number, c: number, d: number) => Math.min(interpolate(s, [a, b], [0, 1], clamp), interpolate(s, [c, d], [1, 0], clamp));
const mixV = (a: V, b: V, k: number): V => [a[0] + (b[0] - a[0]) * k, a[1] + (b[1] - a[1]) * k];
const sh = (c: string, k: number) => {
  const n = parseInt(c.slice(1), 16);
  const r = (n >> 16) & 255, g = (n >> 8) & 255, b = n & 255;
  const t = k < 0 ? 0 : 255, a = Math.abs(k);
  const f = (v: number) => Math.round(v + (t - v) * a);
  return `rgb(${f(r)},${f(g)},${f(b)})`;
};
const tap = (s: number, t0: number, d = 0.28) => {
  const u = (s - t0) / d;
  return u > 0 && u < 1 ? Math.sin(u * Math.PI) : 0;
};
const hablando = (s: number) => {
  for (let i = 0; i < words.length; i++) {
    const w = words[i];
    if (s >= w.t && s < w.t + w.d * 0.88) return 0.1 + 0.3 * Math.abs(Math.sin((s - w.t) * 17 + i));
  }
  return 0;
};

// Anclas: todo tiempo sale de las palabras del guion.
const A = {
  audifonos: en('audifonos'), toco: en('toco'), abrir: en('abrir'), risa: en('risa'), aunque: en('aunque'), quince: en('quince'), suaves: en('suaves'), panq1: en('risa') - 0.2, risas: en('aunque') + 0.2,
  perd1: en('perdoname', 1), grito: en('grito'), perd2: en('perdoname', 2), notas: en('notas'), ojos: en('ojos'),
  lejos: en('lejos'), vio: en('vio'), padre2: en('padre', 2), corrio: en('corrio'), abrazo: en('abrazo'),
  ensename: en('ensename'), correr: en('correr'), reclamos: en('reclamos'), dame: en('dame'), esperar: en('esperar'),
  oidos: en('oidos'), juzgar: en('juzgar'), si: en('si'), cargando: en('cargando'), cuidala: en('cuidala'), llego: en('llego'),
  pon: en('pon'), escuela: en('escuela'), telefono: en('telefono'), ganar: en('ganar'), recuperar: en('recuperar'),
  dejo: en('dejo'), panq2: en('panqueques'), puerta3: en('puerta', 3), salga: en('salga'), jesus: en('jesus'), amen: en('amen'),
};

// ---------- piezas de personaje (vector liso, luz suave, ojos con punto blanco) ----------
const ik = (S: V, Tg: V, L1: number, L2: number, dir: number): V => {
  const dx = Tg[0] - S[0], dy = Tg[1] - S[1];
  const d = Math.max(Math.abs(L1 - L2) + 2, Math.min(L1 + L2 - 1, Math.hypot(dx, dy)));
  const a = Math.atan2(dy, dx);
  const c = Math.max(-1, Math.min(1, (L1 * L1 + d * d - L2 * L2) / (2 * L1 * d)));
  const Ang = Math.acos(c);
  const c1: V = [S[0] + Math.cos(a + Ang) * L1, S[1] + Math.sin(a + Ang) * L1];
  const c2: V = [S[0] + Math.cos(a - Ang) * L1, S[1] + Math.sin(a - Ang) * L1];
  // el codo cae hacia abajo y hacia afuera (dir = lado del brazo: 1 izquierdo en pantalla, -1 derecho)
  const sc1 = c1[1] - dir * (c1[0] - S[0]) * 0.6, sc2 = c2[1] - dir * (c2[0] - S[0]) * 0.6;
  return sc1 >= sc2 ? c1 : c2;
};

const Seg: React.FC<{a: V; b: V; r0: number; r1: number; fill: string; luz?: number}> = ({a, b, r0, r1, fill, luz = 1}) => {
  const dx = b[0] - a[0], dy = b[1] - a[1];
  const L = Math.hypot(dx, dy) || 1;
  let nx = -dy / L, ny = dx / L;
  if (nx + ny > 0) { nx = -nx; ny = -ny; }
  const P = (q: V, r: number, g: number) => `${q[0] + nx * r * g} ${q[1] + ny * r * g}`;
  return (
    <g>
      <path d={`M${P(a, r0, 1)}L${P(b, r1, 1)}L${P(b, r1, -1)}L${P(a, r0, -1)}Z`} fill={fill} />
      <circle cx={a[0]} cy={a[1]} r={r0} fill={fill} />
      <circle cx={b[0]} cy={b[1]} r={r1} fill={fill} />
      {luz > 0 && (
        <>
          <path d={`M${a[0] + nx * r0 * 0.45} ${a[1] + ny * r0 * 0.45}L${b[0] + nx * r1 * 0.45} ${b[1] + ny * r1 * 0.45}`} stroke="#fff" strokeOpacity={0.15 * luz} strokeWidth={Math.max(4, r1 * 0.5)} strokeLinecap="round" fill="none" />
          <path d={`M${a[0] - nx * r0 * 0.6} ${a[1] - ny * r0 * 0.6}L${b[0] - nx * r1 * 0.6} ${b[1] - ny * r1 * 0.6}`} stroke="#000" strokeOpacity={0.14 * luz} strokeWidth={Math.max(4, r1 * 0.55)} strokeLinecap="round" fill="none" />
        </>
      )}
    </g>
  );
};

const Brazo: React.FC<{sh0: V; hand: V; dir: number; L1: number; L2: number; ropa: string; piel: string; manga: 'larga' | 'corta'; r: number}> = ({sh0, hand, dir, L1, L2, ropa, piel, manga, r}) => {
  const dx = hand[0] - sh0[0], dy = hand[1] - sh0[1];
  const d = Math.hypot(dx, dy) || 1;
  const lim = (L1 + L2) * 0.985;
  const kk = d > lim ? lim / d : 1;
  const hd: V = [sh0[0] + dx * kk, sh0[1] + dy * kk];
  const el = ik(sh0, hd, L1, L2, dir);
  const fx = hd[0] - el[0], fy = hd[1] - el[1];
  const fl = Math.hypot(fx, fy) || 1;
  const wr: V = [hd[0] - (fx / fl) * r * 0.8, hd[1] - (fy / fl) * r * 0.8];
  const wr2: V = [wr[0] - (fx / fl) * r * 0.4, wr[1] - (fy / fl) * r * 0.4];
  const ang = (Math.atan2(fy, fx) * 180) / Math.PI;
  const mid: V = [sh0[0] + (el[0] - sh0[0]) * 0.6, sh0[1] + (el[1] - sh0[1]) * 0.6];
  return (
    <g>
      {manga === 'corta' ? (
        <>
          <Seg a={sh0} b={el} r0={r} r1={r * 0.82} fill={piel} />
          <Seg a={el} b={wr} r0={r * 0.82} r1={r * 0.6} fill={piel} />
          <Seg a={sh0} b={mid} r0={r * 1.08} r1={r * 0.98} fill={ropa} />
        </>
      ) : (
        <>
          <Seg a={sh0} b={el} r0={r * 1.04} r1={r * 0.88} fill={ropa} />
          <Seg a={el} b={wr} r0={r * 0.9} r1={r * 0.68} fill={ropa} luz={0.8} />
          <Seg a={wr2} b={wr} r0={r * 0.72} r1={r * 0.72} fill={sh(ropa, -0.2)} luz={0} />
        </>
      )}
      <g transform={`translate(${hd[0]} ${hd[1]}) rotate(${ang})`}>
        <ellipse cx={0} cy={0} rx={r * 0.9} ry={r * 0.64} fill={piel} />
        <ellipse cx={r * 0.25} cy={-dir * r * 0.62} rx={r * 0.46} ry={r * 0.24} fill={sh(piel, -0.06)} />
        <path d={`M${r * 0.15} ${-r * 0.22}L${r * 0.85} ${-r * 0.22}M${r * 0.15} ${r * 0.12}L${r * 0.88} ${r * 0.12}`} stroke={sh(piel, -0.35)} strokeOpacity={0.55} strokeWidth={2.6} strokeLinecap="round" />
      </g>
    </g>
  );
};

type K = {W: number; TL: number; L1: number; L2: number; r: number; ropa: string; piel: string; pelo: string; estilo: 'mono' | 'rizos' | 'coletas' | 'corto'; manga: 'larga' | 'corta'; hem: number; flare: number; rx: number; ry: number; prenda: 'bata' | 'sudadera' | 'vestido' | 'tunica' | 'capa'};
const MAMA: K = {W: 95, TL: 330, L1: 165, L2: 150, r: 26, ropa: '#9a7bd0', piel: '#c98f64', pelo: '#33201a', estilo: 'mono', manga: 'larga', hem: 560, flare: 1.5, rx: 62, ry: 74, prenda: 'bata'};
const CHICA: K = {W: 92, TL: 330, L1: 160, L2: 146, r: 26, ropa: '#3f9a72', piel: '#a97550', pelo: '#2a1812', estilo: 'rizos', manga: 'larga', hem: 260, flare: 1.12, rx: 58, ry: 70, prenda: 'sudadera'};
const NINA: K = {W: 64, TL: 220, L1: 112, L2: 100, r: 18, ropa: '#f2b84b', piel: '#c98f64', pelo: '#33201a', estilo: 'coletas', manga: 'corta', hem: 300, flare: 1.4, rx: 56, ry: 62, prenda: 'vestido'};
const HIJO: K = {W: 84, TL: 330, L1: 160, L2: 142, r: 24, ropa: '#b49a74', piel: '#b97d55', pelo: '#2b1d16', estilo: 'corto', manga: 'larga', hem: 120, flare: 1.2, rx: 52, ry: 62, prenda: 'tunica'};
const PADRE: K = {W: 96, TL: 330, L1: 165, L2: 150, r: 28, ropa: '#3d5f98', piel: '#c08a60', pelo: '#d6d1cb', estilo: 'corto', manga: 'larga', hem: 245, flare: 1.35, rx: 54, ry: 64, prenda: 'capa'};

type CP = {rx: number; ry: number; piel: string; pelo: string; estilo: K['estilo']; look: number; mirarY: number; tilt: number; cierra: number; sonrisa: number; abre: number; ceja: number; lagrima: number; harina: boolean; audifonos: boolean; id: string; espalda: boolean};
const Cabeza: React.FC<CP> = ({rx, ry, piel, pelo, estilo, look, mirarY, tilt, cierra, sonrisa, abre, ceja, lagrima, harina, audifonos, id, espalda}) => {
  const fx = look * 10;
  const hd = sh(pelo, -0.3);
  const hl = sh(pelo, 0.28);
  const ojo = (sg: number) => {
    const ex = sg * rx * 0.42 + fx, ey = -2 + mirarY * 6;
    const ab = 1 - cierra;
    const inner = ey - 25 + (ceja < 0 ? ceja * 8 : -ceja * 4);
    const outer = ey - 24 - ceja * 5;
    return (
      <g key={sg}>
        {cierra > 0.85 ? (
          <path d={`M${ex - 14} ${ey} Q${ex} ${ey + 9} ${ex + 14} ${ey}`} stroke={hd} strokeWidth={4} fill="none" strokeLinecap="round" />
        ) : (
          <>
            <ellipse cx={ex} cy={ey} rx={14} ry={Math.max(2.5, 11 * ab)} fill="#fff" />
            <ellipse cx={ex + look * 4} cy={ey + mirarY * 3} rx={8.5} ry={Math.max(2.5, 8.5 * ab)} fill="#2a1a14" />
            <circle cx={ex + look * 4 + 3} cy={ey + mirarY * 3 - 3 * ab} r={2.6 * ab + 0.6} fill="#fff" />
            <path d={`M${ex - 15} ${ey} Q${ex} ${ey - 13 * ab - 3} ${ex + 15} ${ey}`} stroke={hd} strokeWidth={4} fill="none" strokeLinecap="round" />
          </>
        )}
        <path d={`M${ex - sg * 14} ${inner} Q${ex} ${Math.min(inner, outer) - 6} ${ex + sg * 17} ${outer}`} stroke={hd} strokeWidth={5.5} fill="none" strokeLinecap="round" />
      </g>
    );
  };
  const my = ry * 0.52, mx = fx * 0.7, mw = 18 + sonrisa * 6;
  const frente = `M${-rx - 4} -12C${-rx - 8} ${-ry - 10} ${rx + 8} ${-ry - 10} ${rx + 4} -12C${rx * 0.8} ${-ry * 0.72} ${-rx * 0.2} ${-ry * 0.64} ${-rx - 4} -12Z`;
  return (
    <g transform={`translate(0 ${-(ry + 26)}) rotate(${tilt} 0 ${ry + 26})`}>
      <defs>
        <radialGradient id={`${id}-pf`} cx="35%" cy="30%" r="85%">
          <stop offset="0" stopColor={sh(piel, 0.14)} />
          <stop offset="0.6" stopColor={piel} />
          <stop offset="1" stopColor={sh(piel, -0.2)} />
        </radialGradient>
      </defs>
      {estilo === 'mono' && (
        <>
          <ellipse cx={0} cy={-8} rx={rx + 8} ry={ry + 9} fill={pelo} />
          <circle cx={0} cy={-ry - 22} r={32} fill={pelo} />
          <circle cx={-8} cy={-ry - 30} r={14} fill={hl} opacity={0.35} />
        </>
      )}
      {estilo === 'rizos' &&
        Array.from({length: 16}).map((_, i) => {
          const a = Math.PI * (1.08 + (i / 15) * 0.84) + Math.PI * 0;
          const q = i / 15;
          const px = Math.cos(a) * (rx + 12 + h(i) * 6), py = Math.sin(a) * (ry + 8) * 0.95 + 4 + (q > 0.85 || q < 0.15 ? 28 : 0);
          return <circle key={i} cx={px} cy={py - 6} r={30 + h(i + 3) * 8} fill={i % 3 ? pelo : hd} />;
        })}
      {estilo === 'rizos' && <ellipse cx={0} cy={-14} rx={rx + 6} ry={ry + 2} fill={pelo} />}
      {estilo === 'coletas' && (
        <>
          <ellipse cx={0} cy={-8} rx={rx + 6} ry={ry + 7} fill={pelo} />
          {[-1, 1].map((sg) => (
            <g key={sg}>
              <ellipse cx={sg * (rx + 34)} cy={34} rx={24} ry={46} fill={pelo} transform={`rotate(${sg * 14} ${sg * (rx + 34)} 34)`} />
              <circle cx={sg * (rx + 18)} cy={-4} r={11} fill="#e8587a" />
            </g>
          ))}
        </>
      )}
      {estilo === 'corto' && <ellipse cx={0} cy={-10} rx={rx + 5} ry={ry + 6} fill={pelo} />}
      {[-1, 1].map((sg) => <ellipse key={sg} cx={sg * (rx - 2)} cy={8} rx={11} ry={17} fill={sh(piel, -0.08)} />)}
      {espalda ? (
        <g>
          <ellipse cx={0} cy={-6} rx={rx + 3} ry={ry + 4} fill={pelo} />
          <path d={`M${-rx * 0.8} ${-ry * 0.4}Q0 ${-ry * 0.9} ${rx * 0.8} ${-ry * 0.4}M${-rx * 0.85} 0Q0 ${-ry * 0.4} ${rx * 0.85} 0M${-rx * 0.7} ${ry * 0.4}Q0 ${ry * 0.1} ${rx * 0.7} ${ry * 0.4}`} stroke={hd} strokeWidth={4} fill="none" opacity={0.7} strokeLinecap="round" />
          <path d={`M${-rx * 0.6} ${-ry * 0.8}Q${-rx * 0.1} ${-ry * 1.0} ${rx * 0.4} ${-ry * 0.85}`} stroke="#fff" strokeWidth={9} fill="none" opacity={0.35} strokeLinecap="round" />
          <path d={`M${-rx - 2} ${ry * 0.3}Q0 ${ry * 1.05} ${rx + 2} ${ry * 0.3}L${rx} ${ry * 0.1}Q0 ${ry * 0.6} ${-rx} ${ry * 0.1}Z`} fill={hd} opacity={0.5} />
          {[-1, 1].map((sg) => <ellipse key={sg} cx={sg * (rx + 4)} cy={6} rx={9} ry={16} fill={sh(piel, -0.05)} />)}
        </g>
      ) : (
        <>
          <ellipse cx={0} cy={0} rx={rx} ry={ry} fill={`url(#${id}-pf)`} />
          {[-1, 1].map((sg) => <ellipse key={'r' + sg} cx={sg * rx * 0.6 + fx * 0.5} cy={ry * 0.3} rx={15} ry={9} fill="#e8786a" opacity={0.26} />)}
          {ojo(-1)}
          {ojo(1)}
          <path d={`M${fx * 1.2} 4Q${fx * 1.2 + 9} 20 ${fx * 1.2 - 3} 26`} stroke={sh(piel, -0.3)} strokeWidth={4} fill="none" strokeLinecap="round" opacity={0.6} />
          {abre > 0.04 ? (
            <g>
              <path d={`M${mx - mw} ${my - sonrisa * 5}Q${mx} ${my + abre * 30 + sonrisa * 8} ${mx + mw} ${my - sonrisa * 5}Q${mx} ${my - 4 + sonrisa * 2} ${mx - mw} ${my - sonrisa * 5}Z`} fill="#5a2020" />
              <path d={`M${mx - mw * 0.8} ${my - sonrisa * 4.4}Q${mx} ${my - 4 + sonrisa * 2} ${mx + mw * 0.8} ${my - sonrisa * 4.4}L${mx + mw * 0.7} ${my - sonrisa * 4 + 5 + abre * 3}Q${mx} ${my + 2} ${mx - mw * 0.7} ${my - sonrisa * 4 + 5 + abre * 3}Z`} fill="#fff" opacity={abre > 0.38 ? 0.95 : 0} />
            </g>
          ) : (
            <path d={`M${mx - mw} ${my - sonrisa * 6}Q${mx} ${my + sonrisa * 15} ${mx + mw} ${my - sonrisa * 6}`} stroke="#7a2e2a" strokeWidth={5} fill="none" strokeLinecap="round" />
          )}
          {lagrima > 0 && lagrima < 1 && <ellipse cx={-rx * 0.42 + fx} cy={14 + lagrima * 46} rx={4.5} ry={7} fill="#cfe6ff" opacity={Math.min(1, (1 - lagrima) * 3)} />}
          {harina && (
            <>
              <circle cx={fx * 1.2} cy={14} r={8} fill="#fff" opacity={0.95} />
              <circle cx={fx * 1.2 + 9} cy={20} r={5} fill="#fff" opacity={0.9} />
              <circle cx={-rx * 0.55} cy={22} r={6} fill="#fff" opacity={0.85} />
            </>
          )}
        </>
      )}
      {estilo === 'mono' && !espalda && <path d={frente} fill={pelo} />}
      {estilo === 'corto' && !espalda && <path d={frente} fill={pelo} />}
      {estilo === 'coletas' && !espalda && <path d={frente} fill={pelo} />}
      {estilo === 'rizos' && !espalda && [-1, -0.45, 0.2, 0.75].map((q, i) => <circle key={i} cx={q * rx * 0.85} cy={-ry * 0.7 + Math.abs(q) * 12} r={24} fill={i % 2 ? pelo : hd} />)}
      {audifonos && (
        <>
          <path d={`M${-rx - 8} 0Q${-rx - 12} ${-ry - 36} 0 ${-ry - 36}Q${rx + 12} ${-ry - 36} ${rx + 8} 0`} stroke="#dfe3ee" strokeWidth={13} fill="none" strokeLinecap="round" />
          {[-1, 1].map((sg) => (
            <g key={sg}>
              <ellipse cx={sg * (rx + 6)} cy={8} rx={20} ry={31} fill="#2b2f45" />
              <ellipse cx={sg * (rx + 10)} cy={8} rx={9} ry={20} fill="#3d4466" />
            </g>
          ))}
        </>
      )}
    </g>
  );
};

const Tronco: React.FC<{k: K; id: string; espalda: boolean}> = ({k, id, espalda}) => {
  const {W, TL, ropa, piel, prenda, hem, flare} = k;
  const bottom = TL + hem;
  const body = `M${-W} 22Q${-W} -8 ${-W * 0.7} -14L${-W * 0.2} -22L${W * 0.2} -22L${W * 0.7} -14Q${W} -8 ${W} 22L${W * 0.9} ${TL * 0.7}L${W * flare} ${bottom}L${-W * flare} ${bottom}L${-W * 0.9} ${TL * 0.7}Z`;
  const dark = sh(ropa, -0.26);
  return (
    <g>
      <defs>
        <linearGradient id={`${id}-t`} x1="0" y1="0" x2="1" y2="0">
          <stop offset="0" stopColor={sh(ropa, 0.2)} />
          <stop offset="0.5" stopColor={ropa} />
          <stop offset="1" stopColor={sh(ropa, -0.22)} />
        </linearGradient>
      </defs>
      {prenda === 'sudadera' && <ellipse cx={0} cy={-6} rx={W * 0.62} ry={42} fill={dark} />}
      <rect x={-20} y={-64} width={40} height={74} rx={14} fill={sh(piel, -0.14)} />
      <path d={body} fill={`url(#${id}-t)`} />
      {prenda === 'bata' && !espalda && (
        <>
          <polygon points={`-36,-18 36,-18 0,78`} fill={piel} />
          <path d={`M-38 -18L-4 ${TL * 0.74}M38 -18L4 ${TL * 0.74}`} stroke={dark} strokeWidth={6} fill="none" strokeLinecap="round" />
          <rect x={-W * 0.9} y={TL * 0.7} width={W * 1.8} height={26} fill={dark} opacity={0.8} />
          <circle cx={0} cy={TL * 0.7 + 13} r={13} fill={sh(ropa, -0.35)} />
          <path d={`M-30 ${TL * 0.78}L${-W * 1.2} ${bottom}M30 ${TL * 0.78}L${W * 1.2} ${bottom}M0 ${TL * 0.8}L0 ${bottom}`} stroke="#000" strokeOpacity={0.1} strokeWidth={5} />
        </>
      )}
      {prenda === 'sudadera' && !espalda && (
        <>
          <path d={`M${-W * 0.5} ${TL * 0.62}L${W * 0.5} ${TL * 0.62}L${W * 0.62} ${TL * 0.95}L${-W * 0.62} ${TL * 0.95}Z`} fill={dark} opacity={0.35} />
          <path d={`M-14 -14L-18 90M14 -14L18 90`} stroke="#f1f1f1" strokeWidth={5} strokeLinecap="round" />
          <ellipse cx={0} cy={-12} rx={40} ry={18} fill={sh(piel, -0.1)} />
          <path d={`M-40 -12Q0 18 40 -12`} stroke={dark} strokeWidth={7} fill="none" />
        </>
      )}
      {prenda === 'vestido' && !espalda && (
        <>
          <ellipse cx={0} cy={-10} rx={34} ry={17} fill={piel} />
          <path d={`M-36 -10Q0 24 36 -10`} stroke="#fff" strokeWidth={8} fill="none" />
          <path d={`M${-W * 0.9} ${TL * 0.7}Q0 ${TL * 0.85} ${W * 0.9} ${TL * 0.7}`} stroke="#e4572e" strokeWidth={12} fill="none" />
        </>
      )}
      {prenda === 'tunica' && !espalda && (
        <>
          <polygon points={`-26,-18 26,-18 0,44`} fill={piel} />
          <rect x={-W * 0.9} y={TL * 0.62} width={W * 1.8} height={22} fill="#6b4a2c" />
          <path d={`M-20 ${TL * 0.62 + 22}L-30 ${TL * 0.62 + 90}M12 ${TL * 0.62 + 22}L24 ${TL * 0.62 + 80}`} stroke="#6b4a2c" strokeWidth={7} strokeLinecap="round" />
          <path d={`M${-W * 1.1} ${bottom}l14 -16l16 16l16 -14l16 14l16 -14l16 14l16 -14l16 14l16 -14l16 14l16 -14l14 14`} stroke={sh(ropa, -0.3)} strokeWidth={4} fill="none" opacity={0.6} />
        </>
      )}
      {prenda === 'capa' && (
        <>
          <rect x={-W * 0.9} y={TL * 0.64} width={W * 1.8} height={24} fill="#d9c28a" />
        </>
      )}
    </g>
  );
};

type FP = {k: K; id: string; s: number; hl: V; hr: V; look?: number; mirarY?: number; tilt?: number; cierra?: number; sonrisa?: number; abre?: number; ceja?: number; lagrima?: number; harina?: boolean; audifonos?: boolean; resp?: number; espalda?: boolean; atras?: boolean; pre?: React.ReactNode; children?: React.ReactNode};
const Figura: React.FC<FP> = ({k, id, hl, hr, look = 0, mirarY = 0, tilt = 0, cierra = 0, sonrisa = 0, abre = 0, ceja = 0, lagrima = 0, harina = false, audifonos = false, resp = 0, espalda = false, atras = false, pre, children}) => {
  const sy = 16;
  const com = {L1: k.L1, L2: k.L2, ropa: k.ropa, piel: k.piel, manga: k.manga, r: k.r};
  const brazos = (
    <>
      <Brazo sh0={[-k.W * 0.86, sy + resp * 0.7]} hand={hl} dir={1} {...com} />
      <Brazo sh0={[k.W * 0.86, sy + resp * 0.7]} hand={hr} dir={-1} {...com} />
    </>
  );
  return (
    <g>
      {atras && brazos}
      <g transform={`translate(0 ${resp * 0.7})`}>
        <Tronco k={k} id={id} espalda={espalda} />
      </g>
      {pre}
      <g transform={`translate(0 ${resp * 0.9})`}>
        <Cabeza rx={k.rx} ry={k.ry} piel={k.piel} pelo={k.pelo} estilo={k.estilo} look={look} mirarY={mirarY} tilt={tilt} cierra={cierra} sonrisa={sonrisa} abre={abre} ceja={ceja} lagrima={lagrima} harina={harina} audifonos={audifonos} id={id} espalda={espalda} />
      </g>
      {!atras && brazos}
      {children}
    </g>
  );
};

// ---------- luz de paz: polvo, rayos, fundidos ----------
const Polvo: React.FC<{s: number; n?: number; c?: string}> = ({s, n = 36, c = '255,236,190'}) => (
  <svg width={1080} height={1920} style={{position: 'absolute', left: 0, top: 0, overflow: 'visible'}}>
    {Array.from({length: n}).map((_, i) => {
      const x = ((h(i + 1) * 1140 + s * (5 + (i % 5) * 3) + Math.sin(s * 0.5 + i) * 30) % 1140) - 30;
      const y = ((((h(i + 50) * 2000 - s * (9 + (i % 4) * 5)) % 2000) + 2000) % 2000) - 40;
      const r = 2 + h(i + 9) * 5;
      return <circle key={i} cx={x} cy={y} r={r} fill={`rgba(${c},1)`} opacity={0.2 + 0.3 * (0.5 + 0.5 * Math.sin(s * 0.9 + i * 1.3))} />;
    })}
