      return <polygon key={i} points={`${x0},-100 ${x0 + 110},-100 ${x0 - 560},1500 ${x0 - 760},1500`} fill="url(#rayo)" opacity={op * (0.55 + 0.45 * Math.sin(s * 0.6 + i * 2.1))} />;
