  const c = kf(s, [[0, 0], [A.dejo - 0.2, 0], [A.panq2 - 0.1, 1], [A.panq2 + 1.0, 1], [A.puerta3 + 1.2, 0], [DUR, 0]]);
  const yM = 840 + c * 520;
  const toL = (P: V): V => [(P[0] - xM) / SC, (P[1] - yM) / SC];
  const golpes = [A.toco, A.toco + 0.4, A.toco + 0.8];
  const hit = Math.min(1, golpes.reduce((a, g) => a + Math.max(0, 1 - Math.abs(s - g) / 0.13), 0));
  const atras = win(s, A.toco - 0.6, A.toco - 0.3, A.toco + 1.1, A.toco + 1.5);
  const taps = atras * (1 - hit) - hit * 0.25;
  const heldW = win(s, A.ganar - 0.6, A.ganar - 0.2, A.dejo - 0.3, A.dejo);
  // mano de la puerta (izquierda en pantalla)
