    [A.ganar - 0.7, REST_R], [A.ganar - 0.2, HELD_R], [A.dejo - 0.2, HELD_R], [A.panq2 - 0.1, toL(PR)], [A.panq2 + 0.6, toL(PR)], [A.puerta3 + 0.2, [60, 80]], [A.jesus - 0.2, [22, 128]], [DUR, [22, 128]],
  ]);
  const hab = hablando(s);
  const look = kf(s, [[0, -0.9], [A.audifonos, -0.9], [A.audifonos + 0.5, -0.4], [A.perd1, -0.4], [A.ojos - 0.3, -0.2], [A.ojos + 0.4, -0.9], [A.si, -0.7], [A.ganar - 0.3, -0.5], [A.dejo - 0.3, -0.5], [A.panq2 - 0.2, -0.9], [A.salga - 0.2, -0.9], [A.jesus - 0.4, 0]]);
  const mirarY = kf(s, [[0, 0], [A.audifonos, 0], [A.audifonos + 0.6, 0.7], [A.abrir, 0.7], [A.abrir + 0.5, 0], [A.ojos + 0.3, 0.2], [A.ganar - 0.3, 0.2], [A.recuperar, 0.6], [A.dejo - 0.4, 0.4], [A.panq2 - 0.3, 1], [A.panq2 + 0.9, 1], [A.puerta3 + 1, 0], [DUR, 0]]);
  const tilt = kf(s, [[0, -3], [A.audifonos, -3], [A.audifonos + 0.8, 4], [A.abrir + 0.6, -2], [A.perd1 + 0.4, 7], [A.ojos - 0.2, 5], [A.ojos + 0.5, -3], [A.correr, -3], [A.correr + 0.8, -5], [A.esperar + 0.5, -6], [A.oidos + 0.3, -3], [A.ganar - 0.3, 3], [A.recuperar, -2], [A.panq2, 6], [A.panq2 + 1, 0], [A.jesus, 3], [DUR, 2]]);
  const cierra = kf(s, [[0, 0], [A.perd1 - 0.2, 0], [A.perd1 + 0.4, 1], [A.ojos - 0.2, 1], [A.ojos + 0.2, 0], [A.correr - 0.3, 0], [A.correr + 0.4, 0.5], [A.dame + 0.4, 0.5], [A.esperar + 0.6, 1], [A.suaves - 0.1, 1], [A.oidos - 0.3, 1], [A.oidos + 0.2, 0], [A.ganar - 0.3, 0], [A.recuperar + 0.3, 0.5], [A.dejo, 0], [A.puerta3 + 0.8, 0], [A.jesus - 0.3, 0.2], [A.jesus + 0.2, 1], [A.amen - 0.2, 1], [A.amen + 0.3, 0.3]]);
  const sonrisa = kf(s, [[0, -0.6], [A.perd1, -0.7], [A.ojos + 0.3, -0.5], [A.correr - 0.3, -0.4], [A.correr + 0.6, 0.7], [A.esperar, 0.55], [A.oidos, 0.4], [A.ganar - 0.3, -0.2], [A.recuperar, -0.3], [A.dejo, 0.2], [A.salga, 0.6], [A.jesus, 0.8], [DUR, 0.9]]);
  const ceja = kf(s, [[0, -0.8], [A.perd1, -1], [A.ojos + 0.3, -0.7], [A.correr, -0.2], [A.correr + 0.6, 0.4], [A.esperar, 0.2], [A.ganar - 0.3, -0.6], [A.recuperar, -0.4], [A.salga, 0.3], [DUR, 0.5]]);
  const lag = s > A.perd1 + 3.2 && s < A.perd1 + 5 ? (s - A.perd1 - 3.2) / 1.8 : s > A.recuperar + 0.4 && s < A.recuperar + 2.2 ? (s - A.recuperar - 0.4) / 1.8 : 0;
  const resp = Math.sin(s * 1.5) * 3 + kf(s, [[0, 0], [A.ensename - 0.3, 0], [A.ensename + 0.1, -9], [A.correr + 0.1, -9], [A.correr + 0.7, 3], [A.correr + 1.6, 0]]) * 0.9;
  const bandejaScreen = s >= A.panq2 - 0.05;
  const parpadeo = 0.78 + 0.22 * Math.sin(s * 7.3) * Math.sin(s * 2.9);
  const azul = tono(s, [0, A.salga - 0.2, A.salga + 0.9], ['rgb(110,170,255)', 'rgb(110,170,255)', 'rgb(255,210,120)']);
  return (
    <AbsoluteFill>
      <svg width={1080} height={1920} style={{position: 'absolute', left: 0, top: 0, overflow: 'visible'}}>
        <defs>
          <linearGradient id="pa-pared" x1="0" y1="0" x2="1" y2="1">
            <stop offset="0" stopColor="#c9b5d6" />
            <stop offset="0.6" stopColor="#b59fc4" />
            <stop offset="1" stopColor="#d3a8a0" />
          </linearGradient>
          <linearGradient id="pa-suelo" x1="0" y1="0" x2="0" y2="1">
            <stop offset="0" stopColor="#8a5c3c" />
            <stop offset="1" stopColor="#4d3022" />
          </linearGradient>
          <linearGradient id="pa-puerta" x1="0" y1="0" x2="1" y2="0">
            <stop offset="0" stopColor="#f2e9d8" />
            <stop offset="1" stopColor="#d9ccb4" />
