            <stop offset="0" stopColor="#ffc89a" />
            <stop offset="1" stopColor="#ff9fa0" />
          </linearGradient>
          <linearGradient id="pa-luzsuelo" x1="0" y1="0" x2="0" y2="1">
            <stop offset="0" stopColor={azul} stopOpacity={0.85} />
            <stop offset="1" stopColor={azul} stopOpacity={0} />
          </linearGradient>
          <radialGradient id="pa-oro">
            <stop offset="0" stopColor="#ffe3a0" stopOpacity={0.95} />
            <stop offset="1" stopColor="#ffd27a" stopOpacity={0} />
          </radialGradient>
        </defs>
        <rect x={-700} y={-700} width={2500} height={3400} fill="url(#pa-pared)" />
        {[0, 1, 2, 3, 4, 5].map((i) => <rect key={i} x={-120 + i * 260} y={-100} width={110} height={1900} fill="#fff" opacity={0.05} />)}
        {/* ventana del amanecer detrás de la madre */}
        <rect x={700} y={430} width={470} height={760} fill="url(#pa-cielo)" />
        <circle cx={980} cy={1020} r={110} fill="#fff3c8" opacity={0.85} />
        <path d="M700 1100Q830 1010 950 1090Q1060 1030 1170 1100V1190H700Z" fill="#8a5a8c" opacity={0.7} />
        <rect x={680} y={410} width={510} height={30} fill="#f1e6d4" />
        <rect x={680} y={1190} width={510} height={34} fill="#f1e6d4" />
        <rect x={680} y={410} width={30} height={810} fill="#f1e6d4" />
        <rect x={1170} y={410} width={30} height={810} fill="#f1e6d4" />
        <rect x={925} y={430} width={20} height={760} fill="#f1e6d4" />
        <path d="M710 430Q760 800 700 1190L700 430Z" fill="#e7c3a2" opacity={0.0} />
        {/* marcos en la pared */}
        <g>
          <rect x={540} y={600} width={104} height={136} fill="#e8d6b5" />
          <rect x={550} y={610} width={84} height={116} fill="#8fb4c9" />
          <circle cx={578} cy={655} r={14} fill="#c98f64" />
          <circle cx={608} cy={665} r={11} fill="#e0b08a" />
          <rect x={560} y={685} width={60} height={30} fill="#9a7bd0" />
        </g>
        {/* cuarto detrás de la puerta (se ve al entreabrirse) */}
        <rect x={DOOR.x0} y={DOOR.y0} width={DOOR.x1 - DOOR.x0} height={DOOR.y1 - DOOR.y0} fill={tono(s, [0, A.salga - 0.2, A.salga + 0.9], ['rgb(62,68,128)', 'rgb(62,68,128)', 'rgb(150,112,80)'])} />
        <polygon points={`${DOOR.x1},${DOOR.y0 + 200} ${DOOR.x1},${DOOR.y1} -140,${DOOR.y1} -140,${DOOR.y0 + 480}`} fill="#ffcf7a" opacity={0.5 * oro} />
        {[0, 1, 2, 3, 4, 5].map((i) => <circle key={i} cx={20 + i * 70} cy={DOOR.y0 + 90 + (i % 2) * 40} r={7} fill="#ffe3a0" opacity={0.85 * oro} />)}
        {/* puerta cerrada de la hija */}
        <g transform={`translate(${DOOR.x0} 0) scale(${k} 1) translate(${-DOOR.x0} 0)`}>
          <rect x={DOOR.x0} y={DOOR.y0} width={DOOR.x1 - DOOR.x0} height={DOOR.y1 - DOOR.y0} fill="url(#pa-puerta)" />
          {[[-70, 560, 300, 380], [-70, 1000, 300, 560]].map((p, i) => <rect key={i} x={p[0]} y={p[1]} width={p[2]} height={p[3]} rx={10} fill="none" stroke="#b9a98c" strokeWidth={7} />)}
          {[[270, 560, 150, 380], [270, 1000, 150, 560]].map((p, i) => <rect key={'b' + i} x={p[0]} y={p[1]} width={p[2]} height={p[3]} rx={10} fill="none" stroke="#b9a98c" strokeWidth={7} />)}
          <circle cx={DOOR.x1 - 50} cy={1180} r={26} fill="#d8b04a" />
