        {/* luz de la pantalla bajo la puerta */}
        <polygon points={`30,1742 ${DOOR.x1 - 30},1742 760,2120 -330,2120`} fill="url(#pa-luzsuelo)" opacity={0.65 * parpadeo * (1 - 0.4 * oro)} />
        <rect x={30} y={1738} width={DOOR.x1 - 60} height={7} fill={azul} opacity={0.95} />
