        <polygon points="700,1745 900,1745 1000,2150 520,2150" fill="#ffe3b0" opacity={0.22} />
        {/* madre */}
        <g transform={`translate(${xM} ${yM}) scale(${SC})`}>
          <Figura k={MAMA} id="mama" s={s} hl={hl} hr={hr} look={look} mirarY={mirarY} tilt={tilt} cierra={cierra} sonrisa={sonrisa} abre={hab} ceja={ceja} lagrima={lag} resp={resp} pre={heldW > 0 && !bandejaScreen ? <g transform="translate(0 150)"><Bandeja s={s} /></g> : null} />
        </g>
