};

// ---------- ESCENA 2: recuerdo en la cocina ----------
const Cocina: React.FC<{s: number}> = ({s}) => {
  const u = (s - (A.panq1 - 0.05)) / 1.15;
  const vuelo = u > 0 && u < 1;
  const lift = vuelo ? Math.sin(Math.min(1, u * 1.6) * Math.PI) * 18 : 0;
  const px = 710, py = 1478 - lift;
  const panqY = vuelo ? 1478 - Math.sin(u * Math.PI) * 330 : 1470;
  const girado = vuelo ? Math.cos(u * Math.PI * 2) : 1;
  const risa = s > A.risas - 0.15 ? Math.abs(Math.sin((s - A.risas) * 13)) * Math.exp(-(s - A.risas) * 0.25) : 0;
  const tl = (P: V, ox: number, oy: number, sc: number): V => [(P[0] - ox) / sc, (P[1] - oy) / sc];
  const madreL = tl([px - 110, py + 6], 735, 1130, 1.5);
  const madreR = tl([850, 1498], 735, 1130, 1.5);
