  const salto = Math.abs(Math.sin((s - A.panq1) * 8)) * 12 * (s > A.panq1 && s < A.risas + 1 ? 1 : 0);
  const abreN = s > A.panq1 - 0.2 && s < A.risas + 1.6 ? 0.6 + 0.4 * Math.abs(Math.sin(s * 14)) : 0.2;
  const flour = (s - A.risas);
