        <rect x={20} y={420} width={22} height={430} fill="#fff" /><rect x={318} y={420} width={22} height={430} fill="#fff" /><rect x={170} y={430} width={14} height={400} fill="#fff" />
        <ellipse cx={220} cy={640} rx={420} ry={420} fill="url(#co-sol)" opacity={0.7} />
        {/* gabinetes y colgantes */}
        <rect x={560} y={420} width={560} height={330} rx={14} fill="#d29a56" />
        {[0, 1].map((i) => <rect key={i} x={580 + i * 270} y={440} width={250} height={290} rx={10} fill="#e3b06a" stroke="#b97d3f" strokeWidth={5} />)}
        {[0, 1, 2].map((i) => <g key={i}><path d={`M${420 + i * 40} 400L${420 + i * 40} 520`} stroke="#6b4a2c" strokeWidth={5} /><ellipse cx={420 + i * 40} cy={540} rx={16} ry={26} fill={['#e8587a', '#f2b84b', '#7cc3a0'][i]} /></g>)}
