        {/* harina, tazón */}
        <g transform="translate(985 1420)"><path d="M-60 70L-70 -60Q0 -90 70 -60L60 70Z" fill="#f6f1e6" /><path d="M-30 -10Q0 -50 30 -10Q0 14 -30 -10Z" fill="#e0b060" /></g>
