// ---------- ESCENA 3: el camino del hijo ----------
const HOR = 820;
const scY = (y: number) => Math.max(0.05, ((y - HOR) / 980) * 1.05);

const Camino: React.FC<{s: number}> = ({s}) => {
  const t0 = A.lejos - 0.9;
  const sonY = kf(s, [[t0, 940], [A.abrazo, 1236], [DUR, 1236]]);
  const padY = kf(s, [[t0, 1800], [A.padre2, 1800], [A.abrazo, 1252], [DUR, 1252]]);
  const corre = s > A.padre2 && s < A.abrazo + 0.05;
  const fase = s * 11;
  const sonSc = scY(sonY), padSc = scY(padY);
  const sonX = 548 + Math.sin(s * 1.2) * 4;
  const padX = kf(s, [[t0, 560], [A.padre2, 560], [A.abrazo, 506]]);
  const abrazado = s >= A.abrazo;
  const ab = kf(s, [[A.abrazo - 0.15, 0], [A.abrazo + 0.45, 1]]);
  const lev = kf(s, [[A.vio - 0.2, 0], [A.vio + 0.5, 1]]);
  const hum = Math.sin(s * 2.4) * 3;
  // brazos del padre (vista de espalda)
  const abiertoL: V = [-345, 50 + (corre ? Math.sin(fase) * 14 : 0)], abiertoR: V = [345, 50 + (corre ? -Math.sin(fase) * 14 : 0)];
  const quietoL: V = [-100, 290], quietoR: V = [100, 290];
  const abrazoL: V = [-30 + 70, 70], abrazoR: V = [30 + 60, 90];
  const padHL = abrazado ? mixV(abiertoL, [-40, 170], ab) : mixV(quietoL, abiertoL, lev);
  const padHR = abrazado ? mixV(abiertoR, [152, 40], ab) : mixV(quietoR, abiertoR, lev);
  void abrazoL; void abrazoR;
  // hijo
  const caida = kf(s, [[A.abrazo - 0.1, 0], [A.abrazo + 0.6, 1]]);
  const hijoHL: V = abrazado ? mixV([-100, 292], [-70, 20], ab) : [-100 + Math.sin(fase * 0.5) * 8, 292];
  const hijoHR: V = abrazado ? mixV([100, 292], [96, 30], ab) : [100 - Math.sin(fase * 0.5) * 8, 292];
  const bastonAng = abrazado ? Math.min(82, (s - A.abrazo) * 160) : 0;
  const viento = Math.sin(s * 2.1) * 6;
  const patas = (x: number, y: number, sc: number, ph: number, mov: boolean) => (
    <g transform={`translate(${x} ${y}) scale(${sc})`}>
      <ellipse cx={0} cy={4} rx={150} ry={22} fill="#000" opacity={0.22} />
      {[-1, 1].map((g) => {
        const lift = mov ? Math.max(0, Math.sin(ph + (g > 0 ? 0 : Math.PI))) * 34 : 0;
        return (
          <g key={g}>
            <rect x={g * 40 - 14} y={-66 - lift} width={28} height={54} rx={12} fill="#a8683e" />
            <ellipse cx={g * 40} cy={-14 - lift} rx={30} ry={14} fill="#5a3f2a" />
          </g>
        );
      })}
    </g>
  );
  return (
    <AbsoluteFill>
      <svg width={1080} height={1920} style={{position: 'absolute', left: 0, top: 0, overflow: 'visible'}}>
        <defs>
          <linearGradient id="ca-cielo" x1="0" y1="0" x2="0" y2="1">
            <stop offset="0" stopColor="#3a2a63" />
            <stop offset="0.45" stopColor="#c0627c" />
            <stop offset="1" stopColor="#ffbe74" />
          </linearGradient>
          <linearGradient id="ca-campo" x1="0" y1="0" x2="0" y2="1">
            <stop offset="0" stopColor="#8e8a4a" />
            <stop offset="1" stopColor="#4f5a2c" />
          </linearGradient>
          <linearGradient id="ca-camino" x1="0" y1="0" x2="0" y2="1">
            <stop offset="0" stopColor="#e6b97a" />
            <stop offset="1" stopColor="#a8754a" />
          </linearGradient>
          <radialGradient id="ca-sol">
            <stop offset="0" stopColor="#fff2c0" stopOpacity={1} />
            <stop offset="0.35" stopColor="#ffcf80" stopOpacity={0.6} />
            <stop offset="1" stopColor="#ffb060" stopOpacity={0} />
          </radialGradient>
        </defs>
        <rect x={-700} y={-900} width={2500} height={HOR + 900} fill="url(#ca-cielo)" />
        <circle cx={700} cy={HOR - 10} r={440} fill="url(#ca-sol)" />
        <circle cx={700} cy={HOR - 10} r={74} fill="#fff7d8" />
        {[0, 1, 2, 3].map((i) => <ellipse key={i} cx={((h(i + 7) * 1500 + s * (6 + i * 2)) % 1500) - 200} cy={300 + i * 110} rx={230 + i * 40} ry={24} fill="#ffb3a0" opacity={0.35} />)}
        <path d={`M-700 ${HOR + 6}L-700 ${HOR - 60}Q-300 ${HOR - 130} 100 ${HOR - 50}Q400 ${HOR - 110} 760 ${HOR - 36}Q1100 ${HOR - 100} 1800 ${HOR - 40}L1800 ${HOR + 6}Z`} fill="#6a4a7c" opacity={0.7} />
        <path d={`M-700 ${HOR + 6}L-700 ${HOR - 20}Q-200 ${HOR - 60} 300 ${HOR - 18}Q800 ${HOR - 56} 1300 ${HOR - 14}L1800 ${HOR + 6}Z`} fill="#4b3a64" opacity={0.85} />
        <rect x={-700} y={HOR} width={2500} height={1400} fill="url(#ca-campo)" />
        {/* casa lejana */}
        <g transform={`translate(160 ${HOR - 4})`}><rect x={-22} y={-26} width={44} height={26} fill="#e9d8c0" /><polygon points="-28,-26 0,-48 28,-26" fill="#a8483a" /><rect x={-5} y={-14} width={10} height={14} fill="#ffd27a" /></g>
        {/* camino */}
        <polygon points={`${540 - 12},${HOR} ${540 + 12},${HOR} 1500,2100 -420,2100`} fill="url(#ca-camino)" />
        <polygon points={`${540 - 3},${HOR} ${540 + 3},${HOR} 700,2100 340,2100`} fill="#fff" opacity={0.07} />
        {/* hierba que se mece y árboles */}
        {Array.from({length: 70}).map((_, i) => {
          const f = h(i + 2), lado = i % 2 ? 1 : -1;
          const yy = HOR + 8 + Math.pow(f, 1.8) * 1100;
          const sc = scY(yy) * 1.1 + 0.05;
          const xRoad = 540 + lado * (14 + (yy - HOR) * 0.78);
          const xx = xRoad + lado * (30 + h(i + 40) * 420 * sc * 1.4);
          const sw = Math.sin(s * 2.2 + i) * 9 * sc;
          return <path key={i} d={`M${xx} ${yy}Q${xx + sw} ${yy - 40 * sc} ${xx + sw * 1.8} ${yy - 78 * sc}M${xx + 9 * sc} ${yy}Q${xx + 9 * sc + sw} ${yy - 36 * sc} ${xx + 12 * sc + sw * 1.6} ${yy - 66 * sc}`} stroke={i % 3 ? '#c9b25a' : '#e2cf7a'} strokeWidth={Math.max(2, 7 * sc)} strokeLinecap="round" fill="none" opacity={0.9} />;
        })}
        {[0, 1, 2].map((i) => {
          const yy = HOR + 18 + i * i * 70 + i * 40, sc = scY(yy);
          const xx = 540 - (60 + (yy - HOR) * 0.95), xr = 540 + (80 + (yy - HOR) * 0.95);
          return [xx, xr].map((x, j) => (
            <g key={i + '-' + j} transform={`translate(${x} ${yy}) scale(${sc})`}>
              <rect x={-12} y={-210} width={24} height={210} fill="#5a3b28" />
              <circle cx={0} cy={-250} r={110} fill="#3f6b3a" />
              <circle cx={-40 + Math.sin(s * 1.5 + i) * 4} cy={-280} r={60} fill="#53824a" opacity={0.9} />
            </g>
          ));
        })}
        {/* figuras */}
        {patas(padX, padY, padSc, fase, corre)}
        {patas(sonX, sonY, sonSc, s * 3.2, !abrazado)}
        {/* hijo */}
        <g transform={`translate(${sonX} ${sonY}) scale(${sonSc})`}>
          <g transform={`translate(0 ${-640 + hum + (abrazado ? 0 : Math.abs(Math.sin(s * 3.2)) * 6)})`}>
            {/* piernas */}
            <rect x={-62} y={430} width={40} height={198} rx={14} fill="#a8683e" />
            <rect x={22} y={430} width={40} height={198} rx={14} fill="#a8683e" />
            <g transform={`rotate(${abrazado ? 0 : 5} 0 0)`}>
              <Figura k={HIJO} id="hijo" s={s} hl={hijoHL} hr={hijoHR} look={abrazado ? -0.4 : 0} mirarY={abrazado ? 0 : 0.9} tilt={abrazado ? -13 * ab : 6 - Math.sin(s * 3.2) * 2} cierra={abrazado ? 1 : 0.4} sonrisa={abrazado ? 0.7 : -0.6} abre={0} ceja={abrazado ? -0.6 : -0.9} lagrima={abrazado ? ((s - A.abrazo - 0.3) % 1.3) / 1.3 : 0} resp={Math.sin(s * 3.2) * 3}>
                {!abrazado && (
                  <g transform={`translate(${hijoHL[0]} ${hijoHL[1]}) rotate(${bastonAng})`}>
                    <rect x={-6} y={-320} width={12} height={760} rx={6} fill="#6b4a2c" />
                  </g>
                )}
              </Figura>
            </g>
            {abrazado && (
              <g transform={`translate(${hijoHL[0] - 20} ${hijoHL[1]}) rotate(${bastonAng})`}>
                <rect x={-6} y={-60} width={12} height={760} rx={6} fill="#6b4a2c" opacity={Math.max(0, 1 - (s - A.abrazo) * 0.5)} />
              </g>
            )}
          </g>
        </g>
        {/* padre de espalda: capa y ropa al viento */}
        <g transform={`translate(${padX} ${padY - (corre ? Math.abs(Math.sin(fase)) * 16 * padSc : 0)}) scale(${padSc})`}>
          <g transform={`translate(0 ${-640 + hum})`}>
            <Figura k={PADRE} id="padre" s={s} hl={padHL} hr={padHR} espalda atras={abrazado && ab > 0.5} resp={Math.sin(s * 2) * 2}
              pre={
                <g>
                  <path d={`M-100 -8Q-130 90 ${-150 + viento * (corre ? 4 : 1)} 300Q${-140 + viento} 440 ${-110 + viento} 500Q0 524 ${110 + viento * 2} 500Q${140 + viento * 2} 440 ${150 + viento * 2.5} 300Q${130 + viento} 90 100 -8Q40 -34 0 -34Q-40 -34 -100 -8Z`} fill="#e3cf9c" />
                  <path d={`M-60 120Q0 160 60 120M-70 230Q0 270 70 230`} stroke="#b9a066" strokeWidth={5} fill="none" opacity={0.6} />
                </g>
              }
            />
            {abrazado && (
              <g opacity={ab}>
                {[-1, 1].map((g) => (
                  <g key={g}>
                    <Seg a={[g * 150, 200]} b={[g * 72, 128]} r0={22} r1={18} fill={HIJO.ropa} luz={0.6} />
                    <ellipse cx={g * 60} cy={118} rx={21} ry={16} fill={HIJO.piel} />
                    <path d={`M${g * 46} 112l${g * 10} 8M${g * 56} 108l${g * 10} 8`} stroke="#8a5530" strokeWidth={3} strokeLinecap="round" />
                  </g>
                ))}
              </g>
            )}
          </g>
        </g>
        {/* líneas de viento y hojas */}
        {Array.from({length: 14}).map((_, i) => {
          const x = ((h(i + 11) * 1400 + s * (160 + i * 14)) % 1400) - 150, y = 200 + h(i + 30) * 1500;
          return <path key={i} d={`M${x} ${y}q40 -10 90 0`} stroke="#fff" strokeWidth={3} strokeLinecap="round" opacity={0.2} fill="none" />;
        })}
      </svg>
      <AbsoluteFill style={{background: 'radial-gradient(circle at 65% 42%, rgba(255,214,140,0.4) 0%, transparent 55%)', mixBlendMode: 'screen'}} />
    </AbsoluteFill>
  );
};
function TL_Y(k: K) {
  return k.TL + 20;
}

// ---------- ESCENA 4: la hija, vista por la ventana ----------
const Ventana: React.FC<{s: number}> = ({s}) => {
  const luz = kf(s, [[A.cuidala + 0.6, 0], [A.pon + 0.8, 1], [DUR, 1]]);
  const mirada = kf(s, [[A.llego, 0], [A.llego + 0.6, 1], [A.telefono - 0.6, 1], [A.telefono + 0.2, 0.3]]);
  const scroll = Math.sin(s * 3.1) * 5;
  const hl: V = [-40, 205 + Math.sin(s * 3.1) * 3];
  const hr: V = [40, 203 + scroll];
  const resp = Math.sin(s * 1.3) * 3 + kf(s, [[A.cargando - 0.2, 0], [A.cargando + 0.6, -10], [A.cargando + 1.6, 4], [A.cargando + 2.2, 0]]);
  const sonrisa = kf(s, [[A.si, -0.6], [A.cuidala, -0.7], [A.pon + 0.4, 0.1], [A.escuela, 0.35], [DUR, 0.45]]);
  const swing = Math.sin(s * 2.4) * 14 * Math.exp(-Math.max(0, s - A.escuela) * 0.12);
  const luciernagas = Array.from({length: 9}).map((_, i) => {
    const ta = A.cuidala - 0.1 + i * 0.22, tb = A.pon + 0.5 + i * 0.12;
    const p = Math.max(0, Math.min(1, (s - ta) / (tb - ta)));
    const e = Easing.inOut(Easing.sin)(p);
    const sx = 1180 + h(i) * 120, sy = 760 + h(i + 3) * 700;
    const mx = 960 - h(i + 5) * 160, my = 600 + h(i + 8) * 500;
    const tx = 760 + h(i + 12) * 330, ty = 1130 + h(i + 14) * 230;
    const x = (1 - e) * (1 - e) * sx + 2 * (1 - e) * e * mx + e * e * tx + (p >= 1 ? Math.sin(s * 1.5 + i) * 14 : 0);
    const y = (1 - e) * (1 - e) * sy + 2 * (1 - e) * e * my + e * e * ty + (p >= 1 ? Math.cos(s * 1.8 + i * 2) * 12 : Math.sin(s * 5 + i) * 6);
    const pulso = 0.55 + 0.45 * Math.sin(s * 3.4 + i * 1.9);
    return {x, y, a: p > 0 ? 1 : 0, pulso};
  });
  return (
    <AbsoluteFill>
      <svg width={1080} height={1920} style={{position: 'absolute', left: 0, top: 0, overflow: 'visible'}}>
        <defs>
          <linearGradient id="ve-pared" x1="0" y1="0" x2="1" y2="1">
            <stop offset="0" stopColor="#3a3463" />
            <stop offset="1" stopColor="#262248" />
          </linearGradient>
          <radialGradient id="ve-fire">
            <stop offset="0" stopColor="#fff6b0" stopOpacity={1} />
            <stop offset="0.3" stopColor="#ffe27a" stopOpacity={0.6} />
            <stop offset="1" stopColor="#ffd060" stopOpacity={0} />
          </radialGradient>
          <radialGradient id="ve-tel">
            <stop offset="0" stopColor="#9fd0ff" stopOpacity={0.8} />
            <stop offset="1" stopColor="#6aa0ff" stopOpacity={0} />
          </radialGradient>
          <radialGradient id="ve-calido">
            <stop offset="0" stopColor="#ffe3a0" stopOpacity={0.8} />
            <stop offset="1" stopColor="#ffcf80" stopOpacity={0} />
          </radialGradient>
        </defs>
        <rect x={-700} y={-700} width={2500} height={3400} fill="#0f1224" />
        {/* el cuarto */}
        <rect x={60} y={400} width={960} height={1380} fill="url(#ve-pared)" />
        {Array.from({length: 18}).map((_, i) => <circle key={i} cx={110 + i * 52} cy={470 + Math.sin(i * 0.9) * 28 + (i % 2) * 10} r={7} fill="#ffd78a" opacity={0.5 + 0.4 * Math.sin(s * 2 + i)} />)}
        <path d="M110 470Q500 540 960 470" stroke="#6b5a8c" strokeWidth={3} fill="none" />
        <rect x={150} y={640} width={170} height={230} fill="#b84a66" /><circle cx={235} cy={745} r={44} fill="#ffcf6a" />
        <rect x={380} y={620} width={130} height={170} fill="#4d8fb3" /><path d="M392 770L445 690L500 770Z" fill="#e6efe0" />
        {/* cabecera */}
        <rect x={250} y={760} width={600} height={500} rx={36} fill="#6b4a3a" />
        <rect x={280} y={790} width={540} height={440} rx={26} fill="#7d5845" />
